css:
@page {
    size: A4;
    margin: 1cm;
}
.booking-confirmation {
    width: 100%;
    font-family: Arial, sans-serif;
    font-size: 12px;
}
.header {
    text-align: center;
}
.header img {
    display: block;
    margin: 0 auto;
}
.details-table,
.totals table,
.addons-table {
    width: 100%;
    border-collapse: collapse;
}
.details-table td {
    padding: 5px;
}
.details-table td:first-child {
    font-weight: bold;
    width: 30%;
}
.details-table td:last-child {
    width: 70%;
}
.section {
    margin-bottom: 15px;
}
.totals {
    margin-top: 15px;
}
@media print {
    .interactive-elements {
        display: none;
    }
}
